<script>
(()=>{
    const templates=<?= json_encode($journalTemplatePayload,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT|JSON_UNESCAPED_SLASHES) ?>;
    const journals=<?= json_encode($journalEditPayload,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT|JSON_UNESCAPED_SLASHES) ?>;
    const journalModal=document.getElementById('finance-journal-modal');
    const templateModal=document.getElementById('finance-journal-template-modal');
    const ensureHidden=(form,name)=>{let field=form.elements[name];if(!field){field=document.createElement('input');field.type='hidden';field.name=name;form.appendChild(field);}return field;};
    const populateRows=(form,values)=>{const body=form.querySelector('[data-finance-lines-body]'),prototype=body?.querySelector('[data-finance-line]');if(!body||!prototype||!Array.isArray(values)||values.length===0)return;body.innerHTML='';values.forEach(data=>{const row=prototype.cloneNode(true);row.querySelectorAll('[data-line-field]').forEach(field=>{const value=data[field.dataset.lineField];if(value!==undefined)field.value=typeof value==='object'?JSON.stringify(value):String(value);});body.appendChild(row);});};
    const populate=(modal,data,keyName)=>{const form=modal?.querySelector('form');if(!form)return;form.reset();ensureHidden(form,keyName).value=data[keyName]||'';Object.entries(data).forEach(([name,value])=>{const field=form.elements[name];if(!field||name==='rows')return;if(field.type==='checkbox')field.checked=Boolean(Number(value));else field.value=String(value??'');});populateRows(form,data.rows||[]);};
    document.querySelector('[data-journal-template-select]')?.addEventListener('change',event=>{const template=templates[event.target.value];if(!template)return;populateRows(event.target.form,template.rows);event.target.form.elements.entry_type.value=template.entry_type;event.target.form.elements.remarks.value=template.remarks||'';});
    const journalRows=document.querySelectorAll('.yovel-hr-two-panel section tbody > tr');Object.values(journals).forEach((journal,index)=>{if(journal.document_status!=='DRAFT'||!journalRows[index])return;const actions=journalRows[index].querySelector('td:last-child > div');if(!actions)return;const button=document.createElement('button');button.type='button';button.className='inline-flex size-8 items-center justify-center rounded-md border';button.dataset.recordModalOpen='finance-journal-modal';button.title='Edit draft';button.setAttribute('aria-label','Edit draft');button.innerHTML='<span class="material-symbols-rounded text-base">edit</span>';button.addEventListener('click',()=>populate(journalModal,journal,'journal_entry_key'));actions.prepend(button);});
    document.querySelector('[data-record-modal-open="finance-journal-modal"]')?.addEventListener('click',event=>{if(!event.currentTarget.title)populate(journalModal,{rows:[{},{}]},'journal_entry_key');});
    const templateItems=document.querySelectorAll('.yovel-hr-two-panel aside .divide-y > div');Object.entries(templates).forEach(([key,template],index)=>{const item=templateItems[index];if(!item)return;item.classList.add('flex','items-center','justify-between','gap-2');const button=document.createElement('button');button.type='button';button.className='inline-flex size-8 shrink-0 items-center justify-center rounded-md border';button.dataset.recordModalOpen='finance-journal-template-modal';button.title='Edit template';button.setAttribute('aria-label','Edit template');button.innerHTML='<span class="material-symbols-rounded text-base">edit</span>';button.addEventListener('click',()=>populate(templateModal,{journal_template_key:key,...template},'journal_template_key'));item.appendChild(button);});
    document.querySelector('[data-record-modal-open="finance-journal-template-modal"]')?.addEventListener('click',event=>{if(!event.currentTarget.title)populate(templateModal,{rows:[{},{}]},'journal_template_key');});
    [journalModal,templateModal].forEach(modal=>{if(!modal?.dataset.financeRehydrate)return;try{const data=JSON.parse(modal.dataset.financeRehydrate||'{}');const rows=JSON.parse(data.rows_json||'[]');populate(modal,{...data,rows},modal===journalModal?'journal_entry_key':'journal_template_key');}catch(error){console.error('Finance form rehydration failed.',error);}});
    document.querySelectorAll('[data-journal-amend-open]').forEach(button=>button.addEventListener('click',()=>{const modal=document.getElementById('finance-journal-repair-modal');modal.querySelector('[data-journal-amend-key]').value=button.dataset.journalKey;modal.querySelector('[data-journal-amend-label]').textContent=button.dataset.journalNumber;modal.querySelector('[name="journal_no"]').value=button.dataset.journalNumber+'-A1';}));
})();
</script>
